import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"Talos-II Tianshi Academy Announcements","description":"","frontmatter":{"translationSource":{"title":"塔卫二天师府学院公告","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/talos-ii-tianshi-academy-announcements"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/talos-ii-tianshi-academy-announcements"}]]},"headers":[],"relativePath":"talos-ii-tianshi-academy-announcements.md","filePath":"logistics/src/page-SboV353S6KTHg6EWajOub8.md"}'),r={name:"talos-ii-tianshi-academy-announcements.md"};function i(s,e,p,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="talos-ii-tianshi-academy-announcements" tabindex="-1">Talos-II Tianshi Academy Announcements <a class="header-anchor" href="#talos-ii-tianshi-academy-announcements" aria-label="Permalink to &quot;Talos-II Tianshi Academy Announcements&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>SboV353S6KTHg6EWajOub8</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=SboV353S6KTHg6EWajOub8" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-rhEbMIPJZuRyzfIw3NG0TC"></span></p><h2 id="group-announcement-text" tabindex="-1">Group Announcement Text <a class="header-anchor" href="#group-announcement-text" aria-label="Permalink to &quot;Group Announcement Text&quot;">​</a></h2><p><span class="mark-grey">*Keep the group announcement short and limited to essential information.</span></p><p>Before asking the group for blueprint support, first watch the videos, read the documentation, or consult the encyclopedia. Documentation link:</p><p><a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a></p><p>Ask other members for help if those sources do not answer your question.</p><p>When asking for blueprint support, first show production reports for the following items:<br> (Star items in the report to pin them for easy display.) Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprigen, Hetogen, Pyrogen, SC Wuling Battery (pin them with report stars).</p><p>We do not guarantee answers from members other than the support staff (group moderators). Please also understand the situation before challenging the support staff.</p><p>As a rule, consult the videos, documentation, and game encyclopedia before asking. Do not repeat simple questions that already have answers; ask about material that is absent, unclear, or easy to overlook.</p><p>Sensitive content is prohibited and results in removal from the group. Personal attacks are prohibited even if you were attacked first, and result in a long mute. Chat unrelated to AIC is discouraged. Contact a moderator or the group owner privately if you want to study further or appeal a decision.</p><p>The group removes inactive members weekly, retaining moderators and those active within the past week.</p><p><span id="source-block-Jhl7Wbb9J03WQtic78XjeP"></span></p><h2 id="group-moderation-rules" tabindex="-1">Group Moderation Rules <a class="header-anchor" href="#group-moderation-rules" aria-label="Permalink to &quot;Group Moderation Rules&quot;">​</a></h2><p><span class="mark-grey">*Moderation rules should clearly record possible situations and their penalties. Colored annotations may explain why a rule was adopted.</span></p><p>Before asking the group for help, you are encouraged to watch the videos, read the documentation, or consult the in-game encyclopedia <span class="mark-grey">(reportedly an effective way to improve the support staff&#39;s opinion of you)</span>. Video links are included in the documentation, so only the documentation link is given:<br> 1.5 Automatic Maximum Gross Production—scroll down for troubleshooting, additional features...<br> If you want to learn more about the AIC principles, the developers have linked the required reading in that document. Questions arising from studying AIC principles are especially welcome.</p><p>Whenever you ask the group for help, show the following items <span class="mark-grey">to make diagnosis much more efficient</span>:<br> (Star items in the report to pin them for easy display.) Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprigen, Hetogen, Pyrogen, SC Wuling Battery (default sort, ascending) <span class="mark-grey">(failing to comply may irritate the support staff or cause them to ignore you)</span>.</p><p>Sensitive content is prohibited, including but not limited to horror, gore, sexually suggestive material, and monetary transactions; anyone posting it is removed immediately. Keep unrelated chat to a minimum, including other games, the original Arknights, gacha pulls, combat rotation planning, and unconventional zipline tricks; a mute may be imposed depending on the situation.</p><p>Take the answers of support staff (group moderators<span class="mark-grey">, currently excluding the group owner</span>) as the reference <span class="mark-grey">(they are not necessarily always right, but they undeniably know the lines better than most people and can contact the developers at any time)</span>. Do not readily trust replies from other channels, and do not stubbornly insist on your own view when consulting support staff.</p><p>As a rule, we do not accept simple questions asked without first consulting the videos, documentation, or game encyclopedia, which answer many common questions. <span class="mark-grey">A question may take you only a few words, but large numbers of people repeatedly asking the same thing drain the support staff&#39;s energy, enthusiasm, and goodwill. To preserve their energy for difficult cases that need them more, they may ignore questions easily answered by those sources—</span>other helpful members may answer, of course, but we do not guarantee those answers&#39; accuracy.</p><p>Personal attacks are prohibited, whether by new members, longstanding members, support staff, or developers. Anyone may report them to members or moderators through a temporary private conversation; confirmed cases receive a long mute. <span class="mark-grey">Please pass on knowledge and goodwill rather than hostility, and take responsibility for your words and actions.</span></p><p>To keep space for newcomers and new questions, members who have not spoken for a week are removed at unspecified times each week. If you want to learn more AIC knowledge, apply through a temporary private conversation with a moderator or the group owner.</p><p>Support staff may ignore questions they do not wish to answer. Once you choose to answer, however, respect the other person&#39;s difficulty and questions throughout and take full responsibility for your assistance. Before transferring a problem you cannot solve, identify the next person responsible and clearly inform the questioner. Do not vent or abandon the issue halfway. If either party breaks the rules, anyone, including those involved, may report it to an administrator or the owner; avoid direct confrontations.</p><p><span id="source-block-vA7Yq3jYQxo0dEbUqY38XY"></span></p><h2 id="moderation-records" tabindex="-1">Moderation Records <a class="header-anchor" href="#moderation-records" aria-label="Permalink to &quot;Moderation Records&quot;">​</a></h2><p><span class="mark-grey">*Moderation records have two types. Penalty records should state the group, the member penalized, the general incident, the applicable rule (which may be omitted in obvious cases), and the penalty level. Cleanup records should state the reminder time, who performed the cleanup, and the execution time; recording cleanups is optional.</span></p></div>',1)])])}const m=t(r,[["render",i]]);export{c as __pageData,m as default};
